package main

import (
	"bufio"
	"os"
	"strconv"
)

type FastIO struct {
	reader *bufio.Reader
}

func NewFastIO(r *os.File) *FastIO {
	return &FastIO{reader: bufio.NewReaderSize(r, 1<<16)}
}

func (f *FastIO) readByte() byte {
	b, err := f.reader.ReadByte()
	if err != nil {
		return 0
	}
	return b
}

func (f *FastIO) NextInt() int {
	c := f.readByte()
	for c <= ' ' {
		c = f.readByte()
	}
	neg := false
	if c == '-' {
		neg = true
		c = f.readByte()
	}
	ret := 0
	for c >= '0' && c <= '9' {
		ret = ret*10 + int(c-'0')
		c = f.readByte()
	}
	if neg {
		return -ret
	}
	return ret
}

func (f *FastIO) NextIntArray(n int) []int {
	arr := make([]int, n)
	for i := 0; i < n; i++ {
		arr[i] = f.NextInt()
	}
	return arr
}

func solve(in *FastIO, out *bufio.Writer) {
	n := in.NextInt()
	k := in.NextInt()
	query := in.NextIntArray(n)
	cost := 0
	availableBooks := make(map[int]bool)
	access := make([]int, 81)
	removable := -1

	for i := 0; i < n; i++ {
		access[query[i]]++
	}

	for i := 0; i < n; i++ {
		currentBook := query[i]
		doesNotContain := !availableBooks[currentBook]
		if doesNotContain {
			cost++
		}
		if removable != -1 {
			delete(availableBooks, removable)
			removable = -1
		} else if len(availableBooks) == k && doesNotContain {
			removableBook := -1
			count := k
			known := make(map[int]bool)
			for j := i + 1; j < n && count > 0; j++ {
				if availableBooks[query[j]] && !known[query[j]] {
					count--
					known[query[j]] = true
					removableBook = query[j]
				}
			}
			if removableBook != -1 {
				delete(availableBooks, removableBook)
			} else {
				for b := range availableBooks {
					delete(availableBooks, b)
					break
				}
			}
		}
		availableBooks[currentBook] = true
		access[currentBook]--
		if access[currentBook] == 0 {
			removable = currentBook
		}
	}

	out.WriteString(strconv.Itoa(cost))
	out.WriteString("\n")
}

func main() {
	in := NewFastIO(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	solve(in, out)
}
